var NEW_PERSON_PROFILES5 = {
  yermak: {desc:"Ukrainian film producer and politician (born 1971)", extract:"Andriy Borysovych Yermak is a Ukrainian politician and former film producer who served as the head of the Office of the President of Ukraine from 2020 to 2025.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Andriy_Yermak%2C_Ukrainian_Head_of_Presidential_Administration_at_the_State_Department_in_Washington%2C_D.C._on_November_13%2C_2023_-_%28cropped%29.jpg/330px-Andriy_Yermak%2C_Ukrainian_Head_of_Presidential_Administration_at_the_State_Department_in_Washington%2C_D.C._on_November_13%2C_2023_-_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Andriy_Yermak"},
  poroshenko: {desc:"President of Ukraine from 2014 to 2019", extract:"Petro Oleksiiovych Poroshenko is a Ukrainian politician, oligarch, and former bureaucrat who served as the fifth president of Ukraine from 2014 to 2019. He served as the Minister of Foreign Affairs from 2009 to 2010, and as the Minister of Trade and Economic Development in 2012. From 2007 until 2012, he headed the Council of Ukraine's National Bank. He was elected president in 2014 in a landslide, avoiding the second round of voting by winning 55.46% in the first round.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3f/Official_portrait_of_Petro_Poroshenko.jpg/330px-Official_portrait_of_Petro_Poroshenko.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Petro_Poroshenko"},
  tymoshenko: {desc:"Prime Minister of Ukraine (2005, 2007–2010)", extract:"Yulia Volodymyrivna Tymoshenko is a Ukrainian politician, who served as Prime Minister of Ukraine in 2005, and again from 2007 until 2010; the first woman in Ukraine to hold that position. She has been a member of the Verkhovna Rada as People's Deputy of Ukraine several times between 1997 and 2007, and presently as of 2014, and was First Deputy Prime Minister of Ukraine for the fuel and energy complex from 1999 to 2001. She holds a PhD degree in Economic Sciences, which is known in Ukraine and other countries as a \"Candidate of Sciences\" degree.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/EPP_Congress_2025_Valencia_Day_1_%2854485015623%29_%28cropped_1%29.jpg/330px-EPP_Congress_2025_Valencia_Day_1_%2854485015623%29_%28cropped_1%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Yulia_Tymoshenko"},
  petro: {desc:"President of Colombia from 2022 to 2026", extract:"Gustavo Francisco Petro Urrego is a Colombian politician and economist who served as the 35th president of Colombia from 2022 to 2026. He founded and leads the political party Historic Pact (PH) and is considered the first, and so far only, left-wing president in the recent history of Colombia.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Foto_Oficial_Presidente_Gustavo_Petro_%283x4_cropped%29.jpg/330px-Foto_Oficial_Presidente_Gustavo_Petro_%283x4_cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Gustavo_Petro"},
  cepeda: {desc:"Colombian politician (born 1962)", extract:"Iván Cepeda Castro is a Colombian politician, human rights activist, and philosopher serving in the Senate of Colombia since 2014. He is a member of the Historic Pact political party and is a political leader on the Colombian left. He served in the Chamber of Representatives from 2010 to 2014. He is the founder of the Manuel Cepeda Foundation, named after his father, who was assassinated in 1994. He was the Historic Pact candidate in the 2026 presidential election, losing to Abelardo de la Espriella by less than 1% of the vote.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Iv%C3%A1n_Cepeda_Castro.jpg/330px-Iv%C3%A1n_Cepeda_Castro.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Iv%C3%A1n_Cepeda"},
  khan: {desc:"Prime Minister of Pakistan from 2018 to 2022", extract:"Imran Ahmed Khan Niazi is a Pakistani former cricketer, philanthropist, and politician who served as the 19th prime minister of Pakistan from August 2018 until April 2022. As a cricketer, he captained the Pakistan national cricket team to victory in the 1992 Cricket World Cup. After retiring from cricket, he founded the Shaukat Khanum Memorial Cancer Hospital and Research Centre, Pakistan's first cancer hospital. He is the founder of the political party Pakistan Tehreek-e-Insaf (PTI) and was its chairman from 1996 to 2023.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Prime_Minister_Imran_Khan_Adresses_the_Forum_01.jpg/330px-Prime_Minister_Imran_Khan_Adresses_the_Forum_01.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Imran_Khan"},
  shehbazsharif: {desc:"Prime Minister of Pakistan (2022–2023; 2024–present)", extract:"Mian Muhammad Shehbaz Sharif is a Pakistani politician and businessman who has served as the prime minister of Pakistan since 2024, being the only person to hold it for two consecutive terms, having previously been in the role between 2022 and 2023. He has also served as the chief minister of Punjab three times, spanning over 12 years, making him the longest-serving person in the role and the president of the Pakistan Muslim League (N).", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/Economic_Cooperation_Organization_July_2025_-_1751655083_%28cropped%29.jpg/330px-Economic_Cooperation_Organization_July_2025_-_1751655083_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Shehbaz_Sharif"},
  nawazsharif: {desc:"Prime Minister of Pakistan (1990–1993; 1997–1999; 2013–2017)", extract:"Mian Muhammad Nawaz Sharif is a Pakistani politician and businessman who thrice served as the prime minister of Pakistan, for three non-consecutive terms, first serving from 1990 to 1993, then from 1997 to 1999 and later from 2013 to 2017. He is the longest-serving prime minister in the country's history, having served a total of more than 9 years across three tenures, with each term ending in his ousting.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/PrimeMinisterNawazSharif.jpg/330px-PrimeMinisterNawazSharif.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Nawaz_Sharif"},
  asimmunir: {desc:"Chief of Defence Forces and Chief of the Army Staff of Pakistan (born 1968)", extract:"Field Marshal Syed Asim Munir Ahmed Shah is a Pakistani military officer who is currently serving as Pakistan's first Chief of Defence Forces (CDF) and the 11th Chief of the Army Staff (COAS) of the Pakistan Army concurrently. Prior to becoming the COAS, he was posted at the GHQ as quartermaster general. He is the first army chief of Pakistan who has previously headed both the Military Intelligence and Inter-Services Intelligence.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Field_Marshal_Asim_Munir.jpg/330px-Field_Marshal_Asim_Munir.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Asim_Munir"},
  mishustin: {desc:"Russian politician and economist (born 1966)", extract:"Mikhail Vladimirovich Mishustin is a Russian politician and economist serving as the prime minister of Russia since 2020. He previously served as the director of the Federal Taxation Service from 2010 to 2020.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/Mikhail_Mishustin_%282026-02-25%29.jpg/330px-Mikhail_Mishustin_%282026-02-25%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Mikhail_Mishustin"},
  liqiang: {desc:"Premier of China since 2023", extract:"Li Qiang is a Chinese politician who is the premier of China and the second-ranking member of the Politburo Standing Committee of the Chinese Communist Party (CCP).", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Li_Qiang_meets_Keir_Starmer_Jan_2026.jpg/330px-Li_Qiang_meets_Keir_Starmer_Jan_2026.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Li_Qiang"},
  zhaoleji: {desc:"Chinese politician (born 1957)", extract:"Zhao Leji is a Chinese politician who is the current chairman of the Standing Committee of the National People's Congress and the third-ranking member of the Politburo Standing Committee of the Chinese Communist Party (CCP), behind Xi Jinping, the CCP general secretary, and Li Qiang, the premier.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Zhao_Leji_meets_Keir_Starmer_Jan_2026.jpg/330px-Zhao_Leji_meets_Keir_Starmer_Jan_2026.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Zhao_Leji"},
  wanghuning: {desc:"Chinese politician (born 1955)", extract:"Wang Huning is a Chinese political scientist and politician who is one of the top leaders of the Chinese Communist Party (CCP). He is currently the chairman of the National Committee of the Chinese People's Political Consultative Conference (CPPCC). He has been a leading ideologist in the country since the 1980s. He has been a member of the CCP's Politburo Standing Committee, the highest decision-making body within the party between convocations of the Central Committee and the National Congress, since 2017 (19th).", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Wang_Huning_2025_National_People%27s_Congress.jpg/330px-Wang_Huning_2025_National_People%27s_Congress.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Wang_Huning"},
  caiqi: {desc:"Chief of Staff for CCP general secretary Xi Jinping", extract:"Cai Qi is a Chinese politician, who is the current first-ranked member of the Secretariat of the Chinese Communist Party (CCP), fifth-ranking member of the CCP's Politburo Standing Committee and the director of the CCP General Office, effectively making him the chief of staff to CCP General Secretary Xi Jinping.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/2025%E5%B9%B4%E8%94%A1%E5%A5%87%E4%B9%A6%E8%AE%B0.jpg/330px-2025%E5%B9%B4%E8%94%A1%E5%A5%87%E4%B9%A6%E8%AE%B0.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Cai_Qi"},
  dingxuexiang: {desc:"First-ranking Vice Premier of China since 2023", extract:"Ding Xuexiang is a Chinese politician who is currently the first-ranked vice premier of China and the sixth-ranked member of the Politburo Standing Committee of the Chinese Communist Party.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Ding_Xuexiang_EU_2024_%28cropped%29.jpg/330px-Ding_Xuexiang_EU_2024_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Ding_Xuexiang"},
  lixi: {desc:"Chinese politician (born 1956)", extract:"Li Xi is a Chinese politician who is the current secretary of the Central Commission for Discipline Inspection, the highest supervisory organ of the Chinese Communist Party (CCP), and the seventh-ranking member of the Politburo Standing Committee of the Chinese Communist Party.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Li_Xi_%28cropped%29_%282025%29_01.jpg/330px-Li_Xi_%28cropped%29_%282025%29_01.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Li_Xi"},
  lepen: {desc:"French lawyer and politician (born 1968)", extract:"Marion Anne Perrine \"Marine\" Le Pen is a French lawyer and politician who served as the president of the far-right National Rally party from 2011 to 2021. She ran for the French presidency in the 2012, 2017, and 2022 presidential elections. Le Pen has been the member of the French National Assembly for the 11th constituency of Pas-de-Calais since 2017 and also has been parliamentary party leader of the National Rally in the Assembly since June 2022.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/Marine_Le_Pen_2025_%283x4_cropped%29.jpg/330px-Marine_Le_Pen_2025_%283x4_cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Marine_Le_Pen"},
  starmer: {desc:"Prime Minister of the United Kingdom from 2024 to 2026", extract:"Sir Keir Rodney Starmer is a British politician and former lawyer who served as Prime Minister of the United Kingdom from 2024 to 2026. He was Leader of the Labour Party from 2020 to 2026 and Leader of the Opposition from 2020 to 2024. He was the Member of Parliament (MP) for Holborn and St Pancras from 2015 to 2026. Before entering politics, he was a barrister and served as Director of Public Prosecutions from 2008 to 2013.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/Prime_Minister_Keir_Starmer_Portrait_%28cropped%29.jpg/330px-Prime_Minister_Keir_Starmer_Portrait_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Keir_Starmer"},
  burnham: {desc:"Prime Minister of the United Kingdom since 2026", extract:"Andrew Murray Burnham is a British politician who has served as Prime Minister of the United Kingdom and Leader of the Labour Party since July 2026. He has been Member of Parliament (MP) for Makerfield in Greater Manchester since June 2026, and was Mayor of Greater Manchester from 2017 to 2026; before that he was MP for Leigh from 2001 to 2017 and held several Cabinet positions. Burnham identifies as a socialist and is associated with the Labour Party's soft left; he is also a member of the Co-operative Party, which is allied with Labour. His political ideology has been called \"Manchesterism\".", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/67/Prime_Minister_Andy_Burnham_portrait_%28cropped%29.jpg/330px-Prime_Minister_Andy_Burnham_portrait_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Andy_Burnham"},
  murmu: {desc:"President of India since 2022", extract:"Droupadi Murmu is an Indian politician who has served as the president of India since 2022. She won the 2022 presidential election from the Bharatiya Janata Party (BJP). She is the first person belonging to a tribal community and also the second woman, after Pratibha Patil, to hold the office. She is also the youngest person to occupy the post and the first president born in independent India.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/President_of_India_Droupadi_Murmu_official_portrait_%28cropped%29.jpg/330px-President_of_India_Droupadi_Murmu_official_portrait_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Droupadi_Murmu"},
  felipevi: {desc:"King of Spain since 2014", extract:"Felipe VI is King of Spain, reigning since 2014.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Daiga_Mieri%C5%86a_tiekas_ar_Sp%C4%81nijas_karali_-_53814974005_%28cropped%29-2.jpg/330px-Daiga_Mieri%C5%86a_tiekas_ar_Sp%C4%81nijas_karali_-_53814974005_%28cropped%29-2.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Felipe_VI"},
  prabowo: {desc:"President of Indonesia since 2024", extract:"Prabowo Subianto Djojohadikusumo is an Indonesian politician, businessman, and retired military officer who has served as the eighth president of Indonesia since 2024. He previously served as the 26th minister of defence under President Joko Widodo from 2019 to 2024. Prabowo is Indonesia's third president to have a military background after Suharto and Susilo Bambang Yudhoyono and is the oldest first-term president in Indonesian history.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Prabowo_Subianto_2024_official_portrait.jpg/330px-Prabowo_Subianto_2024_official_portrait.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Prabowo_Subianto"},
  gibran: {desc:"Vice President of Indonesia since 2024", extract:"Gibran Rakabuming Raka is an Indonesian politician and businessman who is serving as the 14th vice president of Indonesia since 2024. Previously the 18th mayor of Surakarta from 2021 to 2024, he is the eldest child of the seventh president of Indonesia, Joko Widodo. He was the running mate of Prabowo Subianto in the 2024 presidential election, winning with almost 59% of the votes.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Gibran_Rakabuming_2024_official_portrait.jpg/330px-Gibran_Rakabuming_2024_official_portrait.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Gibran_Rakabuming_Raka"},
  albanese: {desc:"Prime Minister of Australia since 2022", extract:"Anthony Norman Albanese is an Australian politician who has served as the 31st prime minister of Australia since 2022. He has been the leader of the Labor Party since 2019 and the member of Parliament (MP) for the New South Wales division of Grayndler since 1996.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Anthony_Albanese_portrait_%28re-crop%29.jpg/330px-Anthony_Albanese_portrait_%28re-crop%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Anthony_Albanese"},
  lapid: {desc:"Prime Minister of Israel in 2022", extract:"Yair Lapid is an Israeli politician and former journalist who has been the Leader of the Opposition since January 2023, having previously served in that role from 2020 to 2021. He was prime minister of Israel from July to December 2022, the second alternate prime minister and Minister of Foreign Affairs under Prime Minister Naftali Bennett from 2021 to 2022, and Minister of Finance under Prime Minister Benjamin Netanyahu from 2013 to 2014. He has led the centrist Yesh Atid party since its creation in 2012.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Yair_Lapid_%28D1237-011%29.jpg/330px-Yair_Lapid_%28D1237-011%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Yair_Lapid"},
  gantz: {desc:"Israeli general and politician (born 1959)", extract:"Benjamin \"Benny\" Gantz is an Israeli politician and retired army general. He served as a minister without portfolio from 2023 to 2024, as the minister of defense between 2020 and 2022, and as deputy prime minister between 2021 and 2022. From 2020 to 2021, he was the alternate prime minister.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Israeli_Minister_Benny_Gantz_at_the_Department_of_State_in_Washington%2C_D.C._on_March_5%2C_2024_%28cropped%29.jpg/330px-Israeli_Minister_Benny_Gantz_at_the_Department_of_State_in_Washington%2C_D.C._on_March_5%2C_2024_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Benny_Gantz"},
  herzog: {desc:"President of Israel since 2021", extract:"Isaac Herzog is an Israeli politician who has been serving since 2021 as the president of Israel. He is the first president to have been born in Israel after its Declaration of Independence.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Isaac_Herzog%2C_July_2021_%28D1233-049%29.JPG/330px-Isaac_Herzog%2C_July_2021_%28D1233-049%29.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Isaac_Herzog"},
  villarruel: {desc:"Vice President of Argentina since 2023", extract:"Victoria Eugenia Villarruel is an Argentine politician, lawyer, writer, and activist who has served as the 38th vice president of Argentina since 2023. Described as a conservative politician, she is the founder of the civil association Centro de Estudios Legales sobre el Terrorismo y sus Víctimas, which she has chaired since its inception. She was a member of the Argentine Chamber of Deputies from 2021 to 2023. Villarruel belongs to the La Libertad Avanza political coalition. She has been accused of Argentine state terrorism denial by several media outlets and human rights organisations. Villarruel denies such accusations, maintaining that she does not support the \"National Reorganization Process\".", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Victoria_villarruel_2025_%28cropped%29.jpg/330px-Victoria_villarruel_2025_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Victoria_Villarruel"},
  obi: {desc:"Nigerian opposition leader (born 1961)", extract:"Peter Onwubuasi Gregory Obi is a Nigerian politician, and businessman who served as the governor of Anambra State from 17 March 2006 until his impeachment on 2 November 2006. Reinstated on 9 February 2007, he continued his tenure until 2010 when he was re-elected for a second term which ended on 7 March 2014. A member of the Nigeria Democratic Congress since 2026, Obi was the presidential candidate for Labour Party in the 2023 Nigerian presidential election and he is contesting the 2027 presidential election under Nigeria Democratic Congress.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/Peter_Obi.png/330px-Peter_Obi.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Peter_Obi"},
  abubakar: {desc:"Vice President of Nigeria from 1999 to 2007", extract:"Atiku Abubakar is a Nigerian politician and businessman who served as the vice president of Nigeria from 1999 to 2007 during the presidency of Olusegun Obasanjo. He ran for the office of governor of Adamawa State in 1990 and 1996 unsuccessfully, but won in 1998. Before he was sworn in, he was selected as running mate to former military leader, Olusegun Obasanjo, during the 1999 presidential election and was re-elected in 2003.", photo:"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Atiku_Abubakar_2023.jpg/330px-Atiku_Abubakar_2023.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail", wiki:"https://en.wikipedia.org/wiki/Atiku_Abubakar"},
};

